263	    /**
264	     * Create a birth if breeding conditions are met.
265	     * @return Number of offspring to create.
266	     */
267	    protected final int breed()
268	    {
269	        int births = 0;
270	        if(canBreed() && rand.nextDouble() <= getBreedingProbability()) {
271	            births = rand.nextInt(getMaxLitterSize()) + 1;
272	        }
273	        return births;
274	    }
