276	    /**
277	     * Create offspring in adjacent free locations.
278	     * @param newCreatures A list to receive newborn creatures.
279	     */
280	    protected final void giveBirth(List<Creature> newCreatures)
281	    {
282	        Field field = getField();
283	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
284	        int births = breed();
285	        for(int b = 0; b < births && free.size() > 0; b++) {
286	            newCreatures.add(createOffspring(field, free.remove(0)));
287	        }
288	    }
289	
290	    /**
291	     * Check whether an object is one of the specified classes.
292	     * @param object The object to inspect.
293	     * @param classes The allowed classes.
294	     * @return true if the object matches one of the classes.
295	     */
296	    private boolean isOneOf(Object object, Class<?>... classes)
297	    {
298	        if(object == null) {
299	            return false;
300	        }
301	        for(Class<?> type : classes) {
302	            if(type.isInstance(object)) {
303	                return true;
304	            }
305	        }
306	        return false;
307	    }
308	}

