  1	/**
  2	 * A class representing shared identity and disease-related characteristics of animals.
  3	 *
  4	 * @version 2022/03/02
  5	 */
  6	public abstract class Animal extends Creature
  7	{
  8	    // sex of an animal, 0 = female and 1 = male
  9	    private final int sex;
 10	
 11	    // If the animal is infected by disease.
 12	    private boolean isInfected;
 13	    // If the animal is immuned from the diease.
 14	    private boolean isImmuned;
 15	
 16	    // Track the first step at which the animal is infected;
 17	    protected int infectionStartStep;
 18	
 19	    // total population that is die of disease.
 20	    public static int populationDieOfDisease = 0;
 21	
 22	    public Animal(Field field, Location location)
 23	    {
 24	        super(field, location);
 25	        sex = (int)(Math.round(Math.random()));
 26	        isInfected = false;
 27	        isImmuned = false;
 28	        infectionStartStep = 0;
 29	    }
 30	
 31	    /**
 32	     * get the gender of an animal.
 33	     * @return sex  0 = female and 1 = male.
 34	     */
 35	    public int getSex()
 36	    {
 37	        return sex;
 38	    }
 39	
 40	    /**
 41	     * get whether an animal is infected.
 42	     *
 43	     * @return true if an animal is infected, false otherwise.
 44	     */
 45	    public boolean getIsInfected()
 46	    {
 47	        return isInfected;
 48	    }
 49	
 50	    /**
 51	     * get if an animal is immuned.
 52	     *
 53	     * @return true if an animal is immuned, false otherwise.
 54	     */
 55	    public boolean getIsImmuned()
 56	    {
 57	        return isImmuned;
 58	    }
 59	
 60	    /**
 61	     * set an animal to be infected.
 62	     * @param isInfected
 63	     */
 64	    public void setIsInfected(boolean isInfected)
 65	    {
 66	        this.isInfected = isInfected;
 67	    }
 68	
 69	    /**
 70	     * set an animal to be immuned.
 71	     * @param isImmuned
 72	     */
 73	    public void setIsImmuned(boolean isImmuned)
 74	    {
 75	        this.isImmuned = isImmuned;
 76	    }
 77	
 78	    /**
 79	     *  Make an animal infected while the disease exists.
 80	     *
 81	     *  @param disease disease
 82	     *  @param step current step.
 83	     */
 84	    protected void makeInfected(Disease disease, int step)
 85	    {
 86	        if((!this.getIsImmuned()) && Randomizer.getRandom().nextDouble() <= disease.INFECTION_RATE) {
 87	            setIsInfected(true);
 88	        }
 89	
 90	        // if the animal is infected in current step, record its start step.
 91	        if(getIsInfected() && infectionStartStep == 0) {
 92	            infectionStartStep = step;
 93	        }
 94	    }
 95	
 96	    /**
 97	     * give the animal immunity while condition is met.
 98	     * @param disease disease.
 99	     * @param step int step.
100	     */
101	    protected void ifCanGrantImmunity(Disease disease, int step)
102	    {
103	        // if an animal is infected, it may die. Otherwise assume it gets immuntity from that disease.
104	        if(getIsInfected() && !getIsImmuned()) {
105	            if(step - infectionStartStep >= disease.NUMBER_OF_STEP_TO_WITHSTAND) {
106	                setIsImmuned(true);
107	                setIsInfected(false);
108	            }
109	        }
110	    }
111	
112	    /**
113	     * set an animal to death if it is die of infection.
114	     * Return true if an animal dies of infection
115	     *
116	     * @return true if an animal dies of infection.
117	     */
118	    protected boolean dieOfInfection(Disease disease)
119	    {
120	        // if an animal is infected, it may die. Otherwise assume it gets immuntity from that disease.
121	        if(getIsInfected() && !getIsImmuned()) {
122	            if(Randomizer.getRandom().nextDouble() <= disease.MORTALITY_RATE) {
123	                setDead();
124	                populationDieOfDisease++;
125	                return true;
126	            }
127	        }
128	        return false;
129	    }
130	}

